import{_ as o,o as a,c as t,a2 as r}from"./chunks/framework.CyZTVJbV.js";const l=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"announcements/v1.20/x-thread-ja.md","filePath":"announcements/v1.20/x-thread-ja.md"}'),c={name:"announcements/v1.20/x-thread-ja.md"};function d(s,e,i,n,p,m){return a(),t("div",null,[...e[0]||(e[0]=[r('<p>1/ kiwa v1.20 released。 Streaming 深化 milestone です。 v1.19 (Framework 深化 横軸、 SolidJS Signal + Deno Fresh Islands + HonoJS Cloudflare Workers) の後、 v1.20 は event-driven backbone (Kafka (kafkajs-shaped producer / consumer / admin) + Redpanda (Kafka API 互換 broker + schema registry) + NATS (core pub/sub + JetStream + KV / Object store)) を 1 統一 mock として同時 land しました。 5 semantics (producer / consumer / exactly-once / DLQ / schema-registry) を 1 API surface で扱えます。</p><p>2/ <code>@kiwa-test/streaming</code> v0.1.0 — 3 provider 統一 testing mock。 <code>createKafkaMock({ defaultPartitionCount })</code> は kafkajs-shaped の broker + producer + consumer + admin (deterministic djb2 key-hash partitioner、 <code>partitionAssigner: &#39;range&#39; | &#39;round-robin&#39;</code>)、 <code>createRedpandaMock({ schemaRegistry: true })</code> は Kafka API 互換 broker + colocated <code>SchemaRegistry</code>、 <code>createNatsMock()</code> は core pub/sub + <code>*</code> (single-token) / <code>&gt;</code> (multi-token) subject routing + <code>nats.jetstream()</code> persistent stream + <code>js.kv</code> + <code>js.objectStore</code>。 104 behavior test。</p><p>3/ producer + consumer semantics — Kafka の <code>producer.send</code> は hash(key) mod partitionCount で routing、 全 write は <code>{ topic, partition, offset }</code> を record、 <code>sendBatch(records[])</code> は topic 越しに flatten。 <code>consumer.run({ eachMessage, autoCommit })</code> は assign された各 partition を walk、 <code>commitOffsets(offsets[])</code> で explicit commit、 <code>getCommittedOffset(groupId, topic, partition)</code> で durable marker 参照。 rebalance は member join/leave 時に deterministic に再計算。</p><p>4/ exactly-once semantics — <code>createTransactionalProducer(kafka, { transactionalId })</code> は multi-record atomic commit + abort、 <code>createIdempotentProducer(kafka, { producerId })</code> は per-partition sequence dedup (retry-safe)、 <code>createReadCommittedFilter(consumer)</code> は downstream read から uncommitted / aborted transaction を filter。 3 helper で exactly-once pillar を broker なしで完結。</p><p>5/ DLQ + schema registry — <code>createDeadLetterQueue({ maxRetries, backoffExponent })</code> は retry policy + poison message quarantine + inspect + reprocess flow を任意の consumer に重ねる。 <code>createSchemaRegistry()</code> は <code>registerAvro</code> / <code>registerProtobuf</code> / <code>registerJson</code> + 3 compatibility mode (<code>BACKWARD</code> / <code>FORWARD</code> / <code>FULL</code>) + schema evolution + fail-fast publish gating。 Kafka + Redpanda + NATS が同一 mock surface を共有。</p><p>6/ dogfood app 3 種 — <code>dogfood-kafka-event-pipeline</code> (Kafka producer + consumer group + exactly-once transactional producer + DLQ × fidelity harness 5 scenario) + <code>dogfood-redpanda-schema-registry</code> (Redpanda + 3 Avro schema (v1→v2 additive / v2→v3 breaking / v3→v4 default drop) × BACKWARD / FORWARD / FULL + fail-fast + Kafka API round-trip × 5 scenario) + <code>dogfood-nats-jetstream</code> (NATS core pub/sub + wildcards + JetStream persistent + KV + Object store × 5 scenario)。 全 3 app が 7 軸 release gate PASS。</p><p>7/ 1 new npm package publish — <code>@kiwa-test/streaming</code> v0.1.0 を npm publish。 kiwa runtime fixture は 34 packages。 docs: tutorial 3 本 (31 Kafka + 32 Redpanda + schema registry + 33 NATS JetStream) + additive migration v1.19 → v1.20 + concept doc <code>streaming-testing.md</code> (5 semantics × 6 semantic axis SSOT)。 VitePress sidebar + gh-pages 反映済。 Roadmap: <a href="https://github.com/cardene777/kiwa#roadmap" target="_blank" rel="noreferrer">https://github.com/cardene777/kiwa#roadmap</a> — v1.11 → v1.12 → v1.13 → v1.14 → v1.15 → v1.16 → v1.17 → v1.18 → v1.19 → v1.20 の 10 milestone 連続完遂。</p>',7)])])}const f=o(c,[["render",d]]);export{l as __pageData,f as default};
